// Assuming you have a Sequelize instance named 'sequelize'

const A = sequelize.define('A', { /* ... your A model attributes ... */ });
const B = sequelize.define('B', { userId: { type: DataTypes.INTEGER } });
const C = sequelize.define('C', { userId: { type: DataTypes.INTEGER } });

// Define relationships (if needed)
A.hasOne(B, { foreignKey: 'bId' });
A.hasOne(C, { foreignKey: 'cId' });

async function getQuery() {
